$strSQLSelect = "SELECT DISTINCT inscricao, 
loteamento, 
logradouro||', '||numero AS endereco,
bairro,
'00' AS hierarquia,
area_terreno, 
area_const_total, 
ocupacao,
proprietario
FROM app.t_imobiliario_default
where inscricao = '".$values["chave"]."'";

