	//$values["solicitante"]  = $data["proprietario"];
}
else
{
};
//  Recupera coordenadas e area geo do lote
$strSQLSelect1 = "SELECT DISTINCT app.geo_lote_31983.codgis, 
	st_area(st_transform ((app.geo_lote_31983.geom), 31983)) AS area_terr_geo,
	round (st_x(st_centroid(app.geo_lote_31983.geom))::numeric, 6) AS coordenadax, 
	round (st_y(st_centroid(app.geo_lote_31983.geom))::numeric, 6) AS coordenaday
FROM app.geo_lote_31983
where app.geo_lote_31983.codgis = '".$chave_lt["txt"]."'";

$rsExists1 = db_query($strSQLSelect1,$conn);
$data1 = db_fetch_array($rsExists1);

if($data1)
{
	$values["area_parcela_geo"]  = $data1["area_terr_geo"];
	$values["coordenadas"]  = $data1["coordenadax"].", ".$data1["coordenaday"];
}
else
{
};
//  Recupera informações de Macrozeamento
$strSQLSelect2 = "SELECT DISTINCT	app.geo_lote_31983.codgis,
	app.geo_zoneamento_vigente.grupo,
	app.geo_zoneamento_vigente.zona
FROM
	app.geo_lote_31983
INNER JOIN 
	app.geo_zoneamento_vigente ON ST_Intersects(app.geo_zoneamento_vigente.geom, st_centroid(app.geo_lote_31983.geom))
where 
	app.geo_zoneamento_vigente.geom && (SELECT st_centroid(app.geo_lote_31983.geom) AS centroide FROM app.geo_lote_31983 WHERE app.geo_lote_31983.codgis = '".$chave_lt["txt"]."'".") 
AND
	st_contains(app.geo_zoneamento_vigente.geom, (SELECT st_centroid(app.geo_lote_31983.geom) AS centroide FROM app.geo_lote_31983 WHERE app.geo_lote_31983.codgis = '".$chave_lt["txt"]."'"."))
AND
	app.geo_lote_31983.codgis = '".$chave_lt["txt"]."'";

$rsExists2 = db_query($strSQLSelect2,$conn);
$data2 = db_fetch_array($rsExists2);

if($data2)
{
	$values["macrozoneamento"]  = $data2["grupo"];
}
else
{
	$values["macrozoneamento"]  = "Não localizado";
};
//  Recupera area do lote que esta em APP30m, Marca como APP_30m 'SIM'
$strSQLSelect6 = "SELECT app.geo_app_30m_2019.uid,
	ST_Intersection (app.geo_lote_31983.geom, app.geo_app_30m_2019.geom) As the_geom,
	st_area(st_transform(ST_Intersection(app.geo_lote_31983.geom, app.geo_app_30m_2019.geom), 31983)) AS areapol
FROM app.geo_lote_31983
	INNER JOIN app.geo_app_30m_2019 ON ST_Intersects(app.geo_lote_31983.geom, app.geo_app_30m_2019.geom)
	WHERE app.geo_lote_31983.codgis = '".$chave_lt["txt"]."'";

$rsExists6 = db_query($strSQLSelect6,$conn);
$data6 = db_fetch_array($rsExists6);

if($data6)
{
	$values["app_30m"]  = "Sim";
	$values["area_app_30m"]  = $data6["areapol"];
}
else
{
	$values["app_30m"]  = "Não incide";
	$values["area_app_30m"]  = 0;
};

